{"content":"def word_wrap(text, width):
    if width < 1:
        raise ValueError("width < 1")
    if not text:
        return []
    lines = []
    la = lines.append
    cur = ""
    cur_len = 0
    for w in text.split(" "):
        if not w:
            continue
        lw = len(w)
        if lw > width:
            if cur_len:
                la(cur)
                cur = ""
                cur_len = 0
            p = 0
            # emit full chunks
            while lw - p > width:
                la(w[p:p + width])
                p += width
            cur = w[p:]
            cur_len = lw - p
        elif cur_len == 0:
            cur = w
            cur_len = lw
        elif cur_len + 1 + lw <= width:
            cur += " "
            cur += w
            cur_len += 1 + lw
        else:
            la(cur)
            cur = w
            cur_len = lw
    if cur_len:
        la(cur)
    return lines
